        <div class="reservation-mail-bar"><div><strong><?php echo e($reservationMailSummary['sent'] === $reservationMailSummary['total'] && $reservationMailSummary['total'] > 0 ? 'The reservation mails have already been sent.' : 'All itinerary services are ready for supplier booking.'); ?></strong><small><?php echo e($reservationMailSummary['sent']); ?> sent · <?php echo e($reservationMailSummary['ready']); ?> ready · <?php echo e($reservationMailSummary['missing']); ?> missing supplier email</small></div><form method="POST" action="<?php echo e(route('admin.quotations.reservation-mails.send',$quotation->id)); ?>"><?php echo csrf_field(); ?><button class="batch-mail-button" <?php if($reservationMailSummary['ready']===0): echo 'disabled'; endif; ?>><i data-lucide="send"></i><?php echo e($reservationMailSummary['ready']===0 ? 'Reservation mails sent' : 'Send reservation mails'); ?></button></form></div>
        <section><?php $__empty_1 = true; $__currentLoopData = $reservations; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $reservation): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><article class="reservation-card"><header><div><strong><?php echo e(ucfirst($reservation->reservation_type)); ?> · <?php echo e($reservation->supplier ?: 'Supplier to confirm'); ?></strong><small><?php echo e(\Carbon\Carbon::parse($reservation->starts_at)->format('d M Y H:i')); ?> → <?php echo e(\Carbon\Carbon::parse($reservation->ends_at)->format('d M Y H:i')); ?></small></div><span class="reservation-status"><?php echo e(ucfirst($reservation->status)); ?></span></header><div class="reservation-grid"><div><small>Confirmation</small><strong><?php echo e($reservation->confirmation_number ?: 'Pending'); ?></strong></div><div><small>Assigned</small><strong><?php echo e($reservation->assigned_person ?: 'Unassigned'); ?></strong></div><div><small>Supplier payment</small><strong><?php echo e($quotation->currency); ?> <?php echo e(number_format($reservation->paid_amount,2)); ?> / <?php echo e(number_format($reservation->actual_cost,2)); ?></strong></div><div><small>Payment deadline</small><strong><?php echo e($reservation->payment_deadline ?: 'Not set'); ?></strong></div></div><details class="email-supplier"><summary><i data-lucide="dollar-sign"></i><?php echo e(ucfirst($reservation->reservation_type)); ?> supplier payment</summary><form method="POST" action="<?php echo e(route('admin.reservations.update',$reservation->id)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><label>Booking status<select name="status"><option value="pending" <?php if($reservation->status==='pending'): echo 'selected'; endif; ?>>Pending</option><option value="requested" <?php if($reservation->status==='requested'): echo 'selected'; endif; ?>>Requested</option><option value="confirmed" <?php if($reservation->status==='confirmed'): echo 'selected'; endif; ?>>Confirmed</option><option value="rejected" <?php if($reservation->status==='rejected'): echo 'selected'; endif; ?>>Rejected</option><option value="cancelled" <?php if($reservation->status==='cancelled'): echo 'selected'; endif; ?>>Cancelled</option><option value="completed" <?php if($reservation->status==='completed'): echo 'selected'; endif; ?>>Completed</option></select></label><label>Booking ref / confirmation #<input name="confirmation_number" value="<?php echo e($reservation->confirmation_number); ?>" placeholder="e.g. HL-88472"></label><label><?php echo e($reservation->reservation_type === 'room' ? 'Guest name / room occupant' : 'Guide / driver assigned'); ?><input name="assigned_person" value="<?php echo e($reservation->assigned_person); ?>"></label><label>Vehicle / number plate<input name="number_plate" value="<?php echo e($reservation->number_plate); ?>"></label><label>Supplier price (what you pay the supplier)<input type="number" step=".01" name="actual_cost" value="<?php echo e($reservation->actual_cost); ?>" required></label><label>Amount already paid to supplier<input type="number" step=".01" name="paid_amount" value="<?php echo e($reservation->paid_amount); ?>" required></label><label>Payment due date<input type="date" name="payment_deadline" value="<?php echo e($reservation->payment_deadline); ?>"></label><label>Internal notes<textarea name="notes" rows="2" placeholder="Any notes about this booking / payment"><?php echo e($reservation->notes); ?></textarea></label><button class="legacy-green"><i data-lucide="save"></i>Save changes</button></form><form method="POST" action="<?php echo e(route('admin.reservations.destroy',$reservation->id)); ?>" onsubmit="return confirm('Delete this reservation permanently?')"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="light-button" style="margin-top:4px"><i data-lucide="trash-2"></i>Delete this booking</button></form></details><details class="email-supplier"><summary><i data-lucide="mail"></i>Email accommodation / supplier</summary><form method="POST" action="<?php echo e(route('admin.reservations.email',$reservation->id)); ?>"><?php echo csrf_field(); ?><label>To<input type="email" name="recipient" value="<?php echo e($reservation->supplier_email); ?>" placeholder="reservations@accommodation.com" required></label><label>Subject<input name="subject" value="Reservation request <?php echo e($quotation->reference); ?> · <?php echo e($quotation->client_name); ?>" required></label><label>Message<textarea name="message" rows="5" required>Dear Reservations Team,

Please confirm availability for <?php echo e($reservation->service_title ?? ucfirst($reservation->reservation_type)); ?> for <?php echo e($quotation->client_name); ?> (<?php echo e($quotation->guest_count); ?> guests), from <?php echo e(\Carbon\Carbon::parse($reservation->starts_at)->format('d M Y')); ?> to <?php echo e(\Carbon\Carbon::parse($reservation->ends_at)->format('d M Y')); ?>.

Kindly reply with the confirmation number, final rate and payment deadline.</textarea></label><button class="legacy-green"><i data-lucide="send"></i>Send reservation email</button></form><?php if($reservation->email_history->isNotEmpty()): ?><div class="email-history"><?php $__currentLoopData = $reservation->email_history; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $email): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><span><?php echo e(ucfirst($email->status)); ?> to <?php echo e($email->recipient); ?> · <?php echo e($email->created_at); ?></span><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php endif; ?></details></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="empty-large">No reservations yet. Add services in Program, then reserve them from the proposal.</div><?php endif; ?></section>

